(function () {
  "use strict";

  const textEncoder = new TextEncoder();
  const crcTable = new Uint32Array(256);

  for (let n = 0; n < 256; n += 1) {
    let c = n;
    for (let k = 0; k < 8; k += 1) {
      c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    }
    crcTable[n] = c >>> 0;
  }

  function crc32(bytes) {
    let c = 0xffffffff;
    for (let index = 0; index < bytes.length; index += 1) {
      c = crcTable[(c ^ bytes[index]) & 0xff] ^ (c >>> 8);
    }
    return (c ^ 0xffffffff) >>> 0;
  }

  function xml(value) {
    return String(value == null ? "" : value)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;");
  }

  function encodeCol(col) {
    let result = "";
    let value = col + 1;
    while (value > 0) {
      const mod = (value - 1) % 26;
      result = String.fromCharCode(65 + mod) + result;
      value = Math.floor((value - mod) / 26);
    }
    return result;
  }

  function encodeCell(cell) {
    return `${encodeCol(cell.c)}${cell.r + 1}`;
  }

  function aoaToSheet(rows) {
    const sheet = {};
    let maxRow = 0;
    let maxCol = 0;
    rows.forEach((row, rowIndex) => {
      maxRow = Math.max(maxRow, rowIndex);
      row.forEach((value, colIndex) => {
        maxCol = Math.max(maxCol, colIndex);
        if (value !== undefined && value !== null) {
          const isHyperlink = typeof value === "object" && value.hyperlink;
          const cellValue = isHyperlink ? value.text : value;
          sheet[encodeCell({ r: rowIndex, c: colIndex })] = {
            t: typeof cellValue === "number" ? "n" : "s",
            v: cellValue,
          };
          if (isHyperlink) {
            sheet[encodeCell({ r: rowIndex, c: colIndex })].l = { Target: value.hyperlink };
          }
        }
      });
    });
    sheet["!ref"] = `A1:${encodeCell({ r: maxRow, c: maxCol })}`;
    return sheet;
  }

  function bookNew() {
    return { SheetNames: [], Sheets: {} };
  }

  function bookAppendSheet(workbook, sheet, name) {
    workbook.SheetNames.push(name);
    workbook.Sheets[name] = sheet;
  }

  function decodeCell(address) {
    const match = /^([A-Z]+)(\d+)$/.exec(address);
    let col = 0;
    for (let index = 0; index < match[1].length; index += 1) {
      col = col * 26 + match[1].charCodeAt(index) - 64;
    }
    return { c: col - 1, r: Number(match[2]) - 1 };
  }

  function sheetToXml(sheet) {
    const cells = Object.keys(sheet)
      .filter((key) => key.charAt(0) !== "!")
      .map((key) => Object.assign({ address: key }, decodeCell(key), sheet[key]))
      .sort((a, b) => (a.r - b.r) || (a.c - b.c));
    const rows = new Map();
    cells.forEach((cell) => {
      if (!rows.has(cell.r)) rows.set(cell.r, []);
      rows.get(cell.r).push(cell);
    });

    const ref = sheet["!ref"] || "A1";
    const cols = (sheet["!cols"] || [])
      .map((col, index) => `<col min="${index + 1}" max="${index + 1}" width="${col.wch || 12}" customWidth="1"/>`)
      .join("");
    const rowOptions = sheet["!rows"] || [];
    const rowXml = Array.from(rows.keys())
      .sort((a, b) => a - b)
      .map((rowIndex) => {
        const rowHeight = rowOptions[rowIndex] && rowOptions[rowIndex].hpt;
        const rowAttrs = rowHeight ? ` ht="${rowHeight}" customHeight="1"` : "";
        const cellXml = rows
          .get(rowIndex)
          .map((cell) => {
            const style = cell.s ? ` s="${cell.s}"` : "";
            if (cell.t === "n") {
              return `<c r="${cell.address}"${style}><v>${cell.v}</v></c>`;
            }
            return `<c r="${cell.address}" t="inlineStr"${style}><is><t>${xml(cell.v)}</t></is></c>`;
          })
          .join("");
        return `<row r="${rowIndex + 1}"${rowAttrs}>${cellXml}</row>`;
      })
      .join("");
    const merges = (sheet["!merges"] || [])
      .map((merge) => `<mergeCell ref="${encodeCell(merge.s)}:${encodeCell(merge.e)}"/>`)
      .join("");
    const mergeXml = merges ? `<mergeCells count="${sheet["!merges"].length}">${merges}</mergeCells>` : "";
    const hyperlinks = cells.filter((cell) => cell.l && cell.l.rId);
    const hyperlinkXml = hyperlinks.length
      ? `<hyperlinks>${hyperlinks.map((cell) => `<hyperlink ref="${cell.address}" r:id="${cell.l.rId}"/>`).join("")}</hyperlinks>`
      : "";

    return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">
<dimension ref="${ref}"/>
<sheetViews><sheetView workbookViewId="0"/></sheetViews>
<sheetFormatPr defaultRowHeight="15"/>
${cols ? `<cols>${cols}</cols>` : ""}
<sheetData>${rowXml}</sheetData>
${mergeXml}
${hyperlinkXml}
</worksheet>`;
  }

  function sheetRelationshipsXml(sheet) {
    const cells = Object.keys(sheet)
      .filter((key) => key.charAt(0) !== "!" && sheet[key].l && sheet[key].l.Target)
      .sort();
    if (!cells.length) {
      return "";
    }
    const relationships = cells
      .map((address, index) => {
        sheet[address].l.rId = `rId${index + 1}`;
        return `<Relationship Id="rId${index + 1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/hyperlink" Target="${xml(sheet[address].l.Target)}" TargetMode="External"/>`;
      })
      .join("");
    return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">${relationships}</Relationships>`;
  }

function stylesXml() {
    return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">
<fonts count="4"><font><sz val="11"/><name val="Aptos Serif"/></font><font><b/><sz val="14"/><name val="Aptos Serif"/></font><font><b/><sz val="11"/><name val="Aptos Serif"/></font><font><b/><sz val="12"/><name val="Aptos Serif"/></font></fonts>
<fills count="2"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill></fills>
<borders count="2"><border><left/><right/><top/><bottom/><diagonal/></border><border><left style="thin"><color rgb="FFB7C9C4"/></left><right style="thin"><color rgb="FFB7C9C4"/></right><top style="thin"><color rgb="FFB7C9C4"/></top><bottom style="thin"><color rgb="FFB7C9C4"/></bottom><diagonal/></border></borders>
<cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs>
<cellXfs count="6"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/><xf numFmtId="0" fontId="1" fillId="0" borderId="0" xfId="0" applyFont="1"/><xf numFmtId="0" fontId="2" fillId="0" borderId="0" xfId="0" applyFont="1"/><xf numFmtId="0" fontId="2" fillId="0" borderId="1" xfId="0" applyFont="1" applyBorder="1" applyAlignment="1"><alignment horizontal="center" vertical="center"/></xf><xf numFmtId="0" fontId="3" fillId="0" borderId="1" xfId="0" applyFont="1" applyBorder="1" applyAlignment="1"><alignment horizontal="center" vertical="center"/></xf><xf numFmtId="0" fontId="0" fillId="0" borderId="1" xfId="0" applyBorder="1" applyAlignment="1"><alignment vertical="center" wrapText="1"/></xf></cellXfs>
<cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles>
</styleSheet>`;
  }

  function workbookXml(workbook) {
    const sheets = workbook.SheetNames.map(
      (name, index) => `<sheet name="${xml(name)}" sheetId="${index + 1}" r:id="rId${index + 1}"/>`
    ).join("");
    return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>${sheets}</sheets></workbook>`;
  }

  function workbookRels(workbook) {
    const sheetRels = workbook.SheetNames.map(
      (_, index) => `<Relationship Id="rId${index + 1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet${index + 1}.xml"/>`
    ).join("");
    return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">${sheetRels}<Relationship Id="rId${workbook.SheetNames.length + 1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>`;
  }

  function contentTypes(workbook) {
    const sheetTypes = workbook.SheetNames.map(
      (_, index) => `<Override PartName="/xl/worksheets/sheet${index + 1}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>`
    ).join("");
    return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>${sheetTypes}</Types>`;
  }

  function makeZip(files) {
    const localParts = [];
    const centralParts = [];
    let offset = 0;
    const now = new Date();
    const dosTime = (now.getHours() << 11) | (now.getMinutes() << 5) | Math.floor(now.getSeconds() / 2);
    const dosDate = ((now.getFullYear() - 1980) << 9) | ((now.getMonth() + 1) << 5) | now.getDate();

    function push16(target, value) {
      target.push(value & 255, (value >>> 8) & 255);
    }
    function push32(target, value) {
      target.push(value & 255, (value >>> 8) & 255, (value >>> 16) & 255, (value >>> 24) & 255);
    }

    files.forEach((file) => {
      const name = textEncoder.encode(file.name);
      const data = textEncoder.encode(file.content);
      const crc = crc32(data);
      const local = [];
      push32(local, 0x04034b50);
      push16(local, 20); push16(local, 0); push16(local, 0); push16(local, dosTime); push16(local, dosDate);
      push32(local, crc); push32(local, data.length); push32(local, data.length); push16(local, name.length); push16(local, 0);
      localParts.push(new Uint8Array(local), name, data);

      const central = [];
      push32(central, 0x02014b50);
      push16(central, 20); push16(central, 20); push16(central, 0); push16(central, 0); push16(central, dosTime); push16(central, dosDate);
      push32(central, crc); push32(central, data.length); push32(central, data.length); push16(central, name.length);
      push16(central, 0); push16(central, 0); push16(central, 0); push16(central, 0); push32(central, 0); push32(central, offset);
      centralParts.push(new Uint8Array(central), name);
      offset += local.length + name.length + data.length;
    });

    const centralOffset = offset;
    const centralSize = centralParts.reduce((sum, part) => sum + part.length, 0);
    const end = [];
    push32(end, 0x06054b50); push16(end, 0); push16(end, 0); push16(end, files.length); push16(end, files.length);
    push32(end, centralSize); push32(end, centralOffset); push16(end, 0);
    return new Blob(localParts.concat(centralParts, [new Uint8Array(end)]), {
      type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
    });
  }

  function writeFile(workbook, filename) {
    const files = [
      { name: "[Content_Types].xml", content: contentTypes(workbook) },
      { name: "_rels/.rels", content: '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>' },
      { name: "xl/workbook.xml", content: workbookXml(workbook) },
      { name: "xl/_rels/workbook.xml.rels", content: workbookRels(workbook) },
      { name: "xl/styles.xml", content: stylesXml() },
    ];
    workbook.SheetNames.forEach((name, index) => {
      const sheet = workbook.Sheets[name];
      const rels = sheetRelationshipsXml(sheet);
      files.push({ name: `xl/worksheets/sheet${index + 1}.xml`, content: sheetToXml(sheet) });
      if (rels) {
        files.push({ name: `xl/worksheets/_rels/sheet${index + 1}.xml.rels`, content: rels });
      }
    });
    const blob = makeZip(files);
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    setTimeout(() => URL.revokeObjectURL(link.href), 1000);
  }

  window.XLSX = {
    utils: { aoa_to_sheet: aoaToSheet, book_new: bookNew, book_append_sheet: bookAppendSheet, encode_cell: encodeCell },
    writeFile,
  };
})();
